const response = $input.first().json;
const executions = response.data || [];
const windowStart = Date.now() - (4 * 60 * 60 * 1000); // same as the schedule interval (every 4 hours)
const recent = executions.filter(function(ex) {
  return new Date(ex.startedAt || ex.createdAt).getTime() > windowStart;
});
return recent.map(function(ex) {
  const name = (ex.workflowData && ex.workflowData.name) || ex.workflowId || 'Unknown';
  const data = {
    workflowName: name,
    executionId: ex.id,
    startedAt: ex.startedAt,
    alertMsg: '🚨 CRITICAL — Workflow Crashed (OOM/Abort)\n\nWorkflow: ' + name + '\nExecution: ' + ex.id + '\nTime: ' + ex.startedAt + '\n\n▶ Check n8n: YOUR_N8N_URL'
  };
  return {json: data};
});

// Critical workflows to watch for silence. EMPTY by default: add an entry only for a workflow that can fail silently (hard stop, out of memory).
// Entry format: { id: '<real workflow id>', name: '<display name>', maxMinutesSinceSuccess: <minutes> }
const criticalWorkflows = [];
return criticalWorkflows.map(function(wf) { return {json: wf}; });

const httpItems = $input.all();
const workflowItems = $('Stale Workflow List').all();
const alerts = [];
for (let i = 0; i < httpItems.length; i++) {
  const httpData = httpItems[i].json;
  const wfData = workflowItems[i] ? workflowItems[i].json : null;
  if (!wfData) continue;
  const executions = httpData.data || [];
  if (!executions.length) {
    const alert1 = {alertMsg: '⚠️ WATCHDOG — Silent Failure Detected\n\nWorkflow: ' + wfData.name + '\nLast success: Never\nExpected: every ' + wfData.maxMinutesSinceSuccess + ' min\n\n▶ Check n8n: YOUR_N8N_URL'};
    alerts.push({json: Object.assign({}, wfData, alert1)});
    continue;
  }
  const lastSuccess = new Date(executions[0].startedAt).getTime();
  const minutesSince = (Date.now() - lastSuccess) / 60000;
  if (minutesSince > wfData.maxMinutesSinceSuccess) {
    const h = Math.floor(minutesSince / 60);
    const m = Math.round(minutesSince % 60);
    const alert2 = {minutesSince: Math.round(minutesSince), alertMsg: '⚠️ WATCHDOG — Silent Failure Detected\n\nWorkflow: ' + wfData.name + '\nLast success: ' + h + 'h ' + m + 'm ago\nExpected: every ' + wfData.maxMinutesSinceSuccess + ' min\n\n▶ Check n8n: YOUR_N8N_URL'};
    alerts.push({json: Object.assign({}, wfData, alert2)});
  }
}
return alerts;
